<template>
  <div>
    <div style="margin-left: 25%; margin-right: 25%;">
      <el-input ref="queryInput" v-model="query" size="large" 
        placeholder="Tìm theo Tựa sách, Tác giả, Chủ đề, Mã vạch..." clearable
        @keydown.enter="handleSearch"
        style="position: fixed; top: 50%; width: 50vw;">
        <template #append>
          <el-button aria-label="search" icon="Search" size="large" @click="handleSearch">Tìm kiếm</el-button>
        </template>
      </el-input>
    </div>
  </div>
</template>

<script>
export default {
    data() {
        return {
            query: ''
        }
    },
    methods: {
        handleSearch() {
            if (this.query !== '') {
              this.$router.push(`/books?q=${ this.query }`)
            }
        }
    },
    mounted() {
      this.$refs.queryInput.focus();
      this.root = document.documentElement;
      this.root.style.setProperty("background-image", "url(/api/background/Background-1.png)");
      this.root.style.setProperty("background-size", "cover");
      this.root.style.setProperty("background-position", "center");
      this.root.style.setProperty("background-attachment", "fixed");
    }
}
</script>

